import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { RouterProvider, createRouter } from "@tanstack/react-router";
import { QueryClientProvider } from "@tanstack/react-query";


// Auto-generated by the TanStack Router Vite plugin — DO NOT EDIT MANUALLY
import { routeTree } from "./routeTree.gen";

import { queryClient } from "@/lib/query-client";
import { ErrorPage, NotFoundPage } from "@/components/error-pages";
import { setUnauthorizedHandler } from "@/lib/api";
import { initErrorReporting } from "@/lib/error-reporting";
import { toast } from "@/components/ui/toaster";
import "./index.css";

/**
 * Create the router instance.
 * Pass `context` here for things every route can read (e.g. queryClient).
 */
const router = createRouter({
  routeTree,
  context: { queryClient },
  // Scroll to top on navigation
  scrollRestoration: true,
  // Any render error or unknown URL shows a recoverable page instead of a blank screen.
  defaultErrorComponent: ErrorPage,
  defaultNotFoundComponent: NotFoundPage,
});

initErrorReporting();

// An expired session returns 401: tell the user, then go to /login and come back afterwards.
let redirectingToLogin = false;
setUnauthorizedHandler(() => {
  if (redirectingToLogin) return;
  redirectingToLogin = true;
  const { pathname, search } = window.location;
  toast.error("Your session has expired. Please sign in again.");
  void queryClient.cancelQueries();
  void router
    .navigate({ to: "/login", search: { redirect: `${pathname}${search}` } as never, replace: true })
    .finally(() => { redirectingToLogin = false; });
});

// TypeScript — register the router for full type inference
declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}

const rootEl = document.getElementById("root");
if (!rootEl) throw new Error("No #root element found in index.html");

createRoot(rootEl).render(
  <StrictMode>
    {/* TanStack Query provider — makes useQuery available everywhere */}
    <QueryClientProvider client={queryClient}>
      {/* The router renders the matched route tree */}
      <RouterProvider router={router} />

    </QueryClientProvider>
  </StrictMode>,
);
